@Entity @Table(name="compliance_snapshot") public class ComplianceSnapshotJpaEntity { @Id private String id; private String aiSystemId; private String asOf; private String sha256; @Column(length=20000) private String manifest; protected ComplianceSnapshotJpaEntity(){} public ComplianceSnapshotJpaEntity(String id,String s,String at,String h,String m){this.id=id;aiSystemId=s;asOf=at;sha256=h;manifest=m;} public String getId(){return id;} public String getAiSystemId(){return aiSystemId;} public String getAsOf(){return asOf;} public String getSha256(){return sha256;} public String getManifest(){return manifest;} }
